const body = $json.body ?? $json;
const required = ['customer_name', 'phone', 'address', 'message'];
const missing = required.filter((key) => !String(body[key] ?? '').trim());
if (missing.length) {
  throw new Error(`Faltan campos: ${missing.join(', ')}`);
}
return [{ json: {
  external_message_id: String(body.external_message_id ?? `local-${Date.now()}`),
  customer_name: String(body.customer_name).trim(),
  phone: String(body.phone).trim(),
  address: String(body.address).trim(),
  raw_message: String(body.message).trim()
} }];

const request = $('Normalizar solicitud').first().json;
const products = $input.all().map((item) => item.json);
const normalize = (value) => String(value ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();
const message = normalize(request.raw_message);
const numberWords = { un: 1, una: 1, uno: 1, dos: 2, tres: 3, cuatro: 4, cinco: 5, seis: 6, siete: 7, ocho: 8, nueve: 9, diez: 10 };
const items = [];
for (const product of products) {
  let aliases = product.aliases;
  if (typeof aliases === 'string') {
    try { aliases = JSON.parse(aliases); } catch { aliases = []; }
  }
  aliases = [...(Array.isArray(aliases) ? aliases : []), product.name]
    .map(normalize)
    .sort((a, b) => b.length - a.length);
  const matches = aliases
    .map((alias) => ({ alias, index: message.indexOf(alias) }))
    .filter((match) => match.index >= 0)
    .sort((a, b) => a.index - b.index || b.alias.length - a.alias.length);
  if (!matches.length) continue;
  const match = matches[0];
  const prefix = message.slice(Math.max(0, match.index - 30), match.index);
  const quantityMatch = prefix.match(/(?:^|\s)(\d+|un|una|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)(?:\s*(?:x|de))?\s*$/);
  const rawQuantity = quantityMatch?.[1];
  const quantity = rawQuantity ? (Number(rawQuantity) || numberWords[rawQuantity] || 1) : 1;
  items.push({ sku: product.sku, quantity, matched_alias: match.alias });
}
const payload = { ...request, items };
return [{ json: {
  payload,
  payload_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
  parser: 'local-catalog-fallback',
  recognized_items: items.length
} }];

const rows = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
const row = rows.find((item) => item?.result !== undefined);
if (!row) return [{ json: { ok: false, error: 'MariaDB no devolvió un resultado' } }];
const result = typeof row.result === 'string' ? JSON.parse(row.result) : row.result;
return [{ json: result }];
